const atlas2dBody=muscleBody;
muscleBody=()=>`<div class="anatomy-3d-wrap"><canvas id="muscle-3d" tabindex="0" role="img" aria-label="Modelo muscular 3D. Arraste para girar; use os botões para ampliar e os grupos ao lado para selecionar."></canvas><span class="model-badge">3D INTERATIVO</span><div class="model-tools"><button aria-label="Girar modelo para a esquerda" onclick="rotateAnatomy(-.35)">↶</button><button aria-label="Girar modelo para a direita" onclick="rotateAnatomy(.35)">↷</button><button aria-label="Ampliar modelo" onclick="zoomAnatomy(.12)">+</button><button aria-label="Reduzir modelo" onclick="zoomAnatomy(-.12)">−</button><button onclick="resetAnatomy()">Restaurar</button></div><p class="note">Arraste para girar · toque em um músculo para ver os exercícios.<br>Modelo 3D ilustrativo dos grupos musculares.</p></div>`;
let currentAnatomyDraw=null,currentAnatomyCleanup=null;
window.rotateAnatomy=delta=>{anatomyYaw+=delta;currentAnatomyDraw?.()};window.zoomAnatomy=delta=>{anatomyZoom=Math.max(.65,Math.min(1.5,anatomyZoom+delta));currentAnatomyDraw?.()};window.resetAnatomy=()=>{anatomyYaw=bodySide==='costas'?Math.PI:0;anatomyPitch=0;anatomyZoom=1;currentAnatomyDraw?.()};
const side3d=window.changeBodySide;window.changeBodySide=side=>{anatomyYaw=side==='costas'?Math.PI:0;anatomyPitch=0;side3d(side)};
function initAnatomy3D(){const canvas=$('#muscle-3d');if(!canvas)return;const gl=canvas.getContext('webgl',{antialias:true,alpha:false,preserveDrawingBuffer:true});if(!gl){canvas.parentElement.innerHTML=`<p class="note">O 3D não está disponível neste navegador. Mostrando o mapa 2D.</p>${atlas2dBody()}`;return}
const vs=`attribute vec3 p;attribute vec3 n;uniform vec2 spin;uniform float zoom;uniform float aspect;varying vec3 normal;vec3 rotate(vec3 v){float c=cos(spin.x),s=sin(spin.x);v=vec3(c*v.x+s*v.z,v.y,-s*v.x+c*v.z);c=cos(spin.y);s=sin(spin.y);return vec3(v.x,c*v.y-s*v.z,s*v.y+c*v.z);}void main(){vec3 v=rotate(p*zoom);normal=rotate(n);float d=9.0-v.z;gl_Position=vec4(v.x*2.5/aspect,v.y*2.5,1.105263*d-2.105263,d);}`;
const fs=`precision mediump float;varying vec3 normal;uniform vec3 color;uniform float picking;void main(){vec3 N=normalize(normal);float l=max(dot(N,normalize(vec3(-.6,.8,1.))),0.);float rim=pow(1.-abs(N.z),3.);vec3 lit=color*(.38+.62*l)+vec3(.1)*rim;gl_FragColor=vec4(mix(lit,color,picking),1.);}`;
function shader(type,source){const s=gl.createShader(type);gl.shaderSource(s,source);gl.compileShader(s);if(!gl.getShaderParameter(s,gl.COMPILE_STATUS))throw new Error('Shader 3D indisponível');return s}
const program=gl.createProgram();gl.attachShader(program,shader(gl.VERTEX_SHADER,vs));gl.attachShader(program,shader(gl.FRAGMENT_SHADER,fs));gl.linkProgram(program);gl.useProgram(program);gl.enable(gl.DEPTH_TEST);gl.disable(gl.DITHER);const pos=gl.getAttribLocation(program,'p'),norm=gl.getAttribLocation(program,'n'),spin=gl.getUniformLocation(program,'spin'),zoom=gl.getUniformLocation(program,'zoom'),aspect=gl.getUniformLocation(program,'aspect'),color=gl.getUniformLocation(program,'color'),picking=gl.getUniformLocation(program,'picking');const keys=Object.keys(muscleLibrary);
const meshes=anatomyObjects.map(part=>{const vertices=[],normals=[];const point=(lat,lon)=>{const a=lat*Math.PI/18,b=lon*2*Math.PI/28,q=[Math.sin(a)*Math.cos(b),Math.cos(a),Math.sin(a)*Math.sin(b)];return {p:q.map((v,i)=>v*part.size[i]+part.position[i]),n:q.map((v,i)=>v/part.size[i])}};for(let lat=0;lat<18;lat++)for(let lon=0;lon<28;lon++){const a=point(lat,lon),b=point(lat+1,lon),c=point(lat+1,lon+1),d=point(lat,lon+1);for(const v of [a,b,c,a,c,d]){vertices.push(...v.p);normals.push(...v.n)}}const pBuffer=gl.createBuffer();gl.bindBuffer(gl.ARRAY_BUFFER,pBuffer);gl.bufferData(gl.ARRAY_BUFFER,new Float32Array(vertices),gl.STATIC_DRAW);const nBuffer=gl.createBuffer();gl.bindBuffer(gl.ARRAY_BUFFER,nBuffer);gl.bufferData(gl.ARRAY_BUFFER,new Float32Array(normals),gl.STATIC_DRAW);return {...part,pBuffer,nBuffer,count:vertices.length/3,id:part.key?keys.indexOf(part.key)+1:0}});
function draw(pick=false){if(!canvas.isConnected)return;const rect=canvas.getBoundingClientRect(),ratio=Math.min(2,devicePixelRatio||1);canvas.width=Math.max(1,Math.round(rect.width*ratio));canvas.height=Math.max(1,Math.round(rect.height*ratio));gl.viewport(0,0,canvas.width,canvas.height);gl.clearColor(pick?0:.065,pick?0:.09,pick?0:.065,1);gl.clear(gl.COLOR_BUFFER_BIT|gl.DEPTH_BUFFER_BIT);gl.uniform2f(spin,anatomyYaw,anatomyPitch);gl.uniform1f(zoom,anatomyZoom);gl.uniform1f(aspect,canvas.width/canvas.height);gl.uniform1f(picking,pick?1:0);for(const mesh of meshes){gl.bindBuffer(gl.ARRAY_BUFFER,mesh.pBuffer);gl.enableVertexAttribArray(pos);gl.vertexAttribPointer(pos,3,gl.FLOAT,false,0,0);gl.bindBuffer(gl.ARRAY_BUFFER,mesh.nBuffer);gl.enableVertexAttribArray(norm);gl.vertexAttribPointer(norm,3,gl.FLOAT,false,0,0);const rgb=pick?[mesh.id/255,0,0]:mesh.key===selectedMuscle?[.77,.95,.42]:mesh.key?[.66,.29,.25]:[.38,.47,.45];gl.uniform3fv(color,rgb);gl.drawArrays(gl.TRIANGLES,0,mesh.count)}}
currentAnatomyDraw=()=>draw();let start=null,previous=null,moved=false;canvas.onpointerdown=e=>{start=previous=[e.clientX,e.clientY];moved=false;canvas.setPointerCapture(e.pointerId)};canvas.onpointermove=e=>{if(!previous)return;const delta=[e.clientX-previous[0],e.clientY-previous[1]];if(Math.hypot(e.clientX-start[0],e.clientY-start[1])>5)moved=true;if(moved){anatomyYaw+=delta[0]*.012;anatomyPitch=Math.max(-.65,Math.min(.65,anatomyPitch+delta[1]*.008));draw()}previous=[e.clientX,e.clientY]};canvas.onpointerup=e=>{if(!moved){const rect=canvas.getBoundingClientRect();draw(true);const pixel=new Uint8Array(4);gl.readPixels(Math.floor((e.clientX-rect.left)*canvas.width/rect.width),Math.floor((rect.bottom-e.clientY)*canvas.height/rect.height),1,1,gl.RGBA,gl.UNSIGNED_BYTE,pixel);draw();if(pixel[0]>0&&pixel[0]<=keys.length)window.chooseMuscle(keys[pixel[0]-1])}start=previous=null};canvas.onpointercancel=()=>{start=previous=null};canvas.onwheel=e=>{e.preventDefault();window.zoomAnatomy(e.deltaY<0?.07:-.07)};canvas.onkeydown=e=>{if(['ArrowLeft','ArrowRight','ArrowUp','ArrowDown','+','-'].includes(e.key)){e.preventDefault();if(e.key==='ArrowLeft'||e.key==='ArrowRight')window.rotateAnatomy(e.key==='ArrowLeft'?-.2:.2);else if(e.key==='+'||e.key==='-')window.zoomAnatomy(e.key==='+'?.1:-.1);else{anatomyPitch=Math.max(-.65,Math.min(.65,anatomyPitch+(e.key==='ArrowUp'?-.1:.1)));draw()}}};draw();const observer=new ResizeObserver(()=>draw());observer.observe(canvas);currentAnatomyCleanup=()=>{observer.disconnect();meshes.forEach(m=>{gl.deleteBuffer(m.pBuffer);gl.deleteBuffer(m.nBuffer)});gl.deleteProgram(program);currentAnatomyDraw=null};canvas.addEventListener('webglcontextlost',e=>{e.preventDefault();observer.disconnect();canvas.parentElement.innerHTML=`<p>O 3D foi interrompido. Reabra a aba do mapa.</p>${atlas2dBody()}`});}
const render3d=render;render=function(){currentAnatomyCleanup?.();currentAnatomyCleanup=null;render3d();if(role==='personal'&&page==='treinos'&&trainingTab==='mapa')initAnatomy3D()};


